node -e "
const fs=require('fs'),path=require('path');
const root='c:/Users/james/Videos/deeds-web-app/sveltekit-frontend';
const lines=[];
// 1. Inject latest audit_gates.json if fresh (<24h)
try{
  const runs=fs.readdirSync(path.join(root,'memory/runs')).sort().slice(-1);
  if(runs[0]){
    const gf=path.join(root,'memory/runs',runs[0],'audit_gates.json');
    if(fs.existsSync(gf)&&(Date.now()-fs.statSync(gf).mtimeMs)<86400000){
      const g=JSON.parse(fs.readFileSync(gf,'utf8'));
      const fails=Object.entries(g.gates||{}).filter(([k,v])=>k.startsWith('g')&&typeof v==='number'&&v>0&&!k.includes('consumer')&&!k.includes('pass')&&!k.includes('kmeans')&&!k.includes('som'));
      if(fails.length)lines.push('OPEN AUDIT GATES: '+fails.map(([k,v])=>k+'='+v).join(', '));
      else lines.push('Audit gates: ALL PASS (run '+runs[0]+')');
    }
  }
}catch(e){}
// 2. Inject smoke:graphify status from graph JSON mtime
try{
  const gj=path.join(root,'docs/graph/codebase-graph.json');
  if(fs.existsSync(gj)){
    const age=Math.round((Date.now()-fs.statSync(gj).mtimeMs)/60000);
    lines.push('codebase-graph.json age: '+age+'min'+(age>120?' ⚠️ stale':''));
  }
}catch(e){}
// 3. Inject latest next_actions P0 count
try{
  const runs=fs.readdirSync(path.join(root,'memory/runs')).sort().slice(-1);
  if(runs[0]){
    const na=path.join(root,'memory/runs',runs[0],'next_actions.md');
    if(fs.existsSync(na)){
      const txt=fs.readFileSync(na,'utf8');
      const p0=((txt.match(/^- \[/mg))||[]).length;
      if(p0>0)lines.push('next_actions P0/P1 open items: '+p0+' (see memory/runs/'+runs[0]+'/next_actions.md)');
    }
  }
}catch(e){}
if(lines.length)console.log(JSON.stringify({systemMessage:'[Graph context] '+lines.join(' | ')}));
" 2>/dev/null

